window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4ec9166911cfceb3"]={"versions": [{"id": "FIG-4ec9166911cfceb3", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) der Netzwerkmodi des CAN State Managers (CanSM) in der AUTOSAR Classic Platform. Das Diagramm modelliert die übergeordneten Betriebsmodi für ein CAN-Netzwerk bzw. einen CAN-Kanal sowie die Übergänge zwischen Initialisierung und Kommunikationsmodi.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände:</p>\n<ul class=\"fig-list\"><li><code>CANSM_UNINITED</code>: Uninitialisierter Grundzustand des CanSM.\n</li><li><code>CANSM_NO_COMMUNICATION</code>: Zustand ohne Netzwerkkommunikation; Controller und Transceiver befinden sich im Energiesparmodus.\n</li><li><code>CANSM_SILENT_COMMUNICATION</code>: Abhörmodus; Empfang aktiv, Senden unterbunden.\n</li><li><code>CANSM_FULL_COMMUNICATION</code>: Vollständiger Kommunikationsbetrieb für Senden und Empfangen.\n</li></ul>\n<p class=\"fig-p\">Pseudo-Zustände / Startpunkt:</p>\n<ul class=\"fig-list\"><li><code>PowerOff</code> (Initialzustand / schwarzer Kreis) mit Transition <code>PowerOn</code>.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>CanSM als zustandsführendes Modul.\n</li><li>Angesteuerte Entitäten und Treiber über Aktionen: CAN Transceiver Driver, CAN Controller Driver (CanIf / MCAL) und PDU-Router / Com-PDU-Gruppenverwaltung.\n</li><li>Modus-Benachrichtigung (<code>mode notification</code>) an den Communication Manager (ComM).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf und Zustandsübergänge:</p>\n<ol class=\"fig-list\"><li><code>PowerOn</code> führt aus dem Zustand <code>PowerOff</code> in <code>CANSM_UNINITED</code>.\n<ul class=\"fig-list\"><li>Bei <code>No initialisation</code> verbleibt das System über eine Selbsttransition in <code>CANSM_UNINITED</code>.\n</li></ul>\n</li><li>Bei <code>Initialisation</code> wechselt das System von <code>CANSM_UNINITED</code> nach <code>CANSM_NO_COMMUNICATION</code>. Aktionen: CAN-Transceiver auf Standby schalten, CAN-Controller in den Sleep-Modus versetzen, Modus-Benachrichtigung absetzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_NO_COMMUNICATION</code> bewirkt <code>&quot;Full communication&quot; not requested</code> eine Selbsttransition ohne Zustandswechsel.\n</li></ul>\n</li><li>Von <code>CANSM_NO_COMMUNICATION</code> nach <code>CANSM_FULL_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; requested</code>. Aktionen: Transceiver auf Normalbetrieb setzen, Controller starten, RX- und TX-PDU-Gruppen starten, Modus-Benachrichtigung absetzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_FULL_COMMUNICATION</code> bewirkt <code>&quot;Full communication&quot; requested</code> eine interne/Selbsttransition.\n</li></ul>\n</li><li>Von <code>CANSM_FULL_COMMUNICATION</code> nach <code>CANSM_SILENT_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; not requested</code>. Aktionen: TX-PDU-Gruppe stoppen, PDU-Modus auf <code>&quot;TX Offline&quot;</code> setzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_SILENT_COMMUNICATION</code> bewirkt <code>&quot;Silent communication&quot; requested</code> eine Selbsttransition.\n</li></ul>\n</li><li>Von <code>CANSM_SILENT_COMMUNICATION</code> nach <code>CANSM_FULL_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; requested</code>. Aktionen: PDU-Modus auf <code>&quot;Online&quot;</code> setzen, TX-PDU-Gruppe starten, Modus-Benachrichtigung absetzen.\n</li><li>Von <code>CANSM_SILENT_COMMUNICATION</code> nach <code>CANSM_NO_COMMUNICATION</code>: Auslöser ist <code>&quot;No communication&quot; requested</code>. Aktionen: RX-PDU-Gruppe stoppen, CAN-Controller in den Sleep-Modus versetzen, Transceiver auf Standby setzen, Modus-Benachrichtigung absetzen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Kommunikationszustände und Transitionen des CanSM gemäß AUTOSAR-Spezifikation. Implementierer müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Zustandswechsel nur über die spezifizierten Trigger (Aufrufe durch ComM) erfolgen.\n</li><li>Alle geforderten Aktionen (Transceiver-Modus, Controller-Status, PDU-Gruppen-Freigaben und ComM-Modusbenachrichtigungen) synchron bzw. in der definierten Sequenz bei Zustandsübergängen ausgeführt werden.\n</li><li>Ungültige Anfragen durch entsprechende Selbsttransitionen abgewiesen bzw. ignoriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d213ab5e4ff49dc8", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) der Netzwerkmodi des CAN State Managers (CanSM) in der AUTOSAR Classic Platform. Das Diagramm modelliert die übergeordneten Betriebsmodi für ein CAN-Netzwerk bzw. einen CAN-Kanal sowie die Übergänge zwischen Initialisierung und Kommunikationsmodi.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zustände:</p>\n<ul class=\"fig-list\"><li><code>CANSM_UNINITED</code>: Uninitialisierter Grundzustand des CanSM.\n</li><li><code>CANSM_NO_COMMUNICATION</code>: Zustand ohne Netzwerkkommunikation; Controller und Transceiver befinden sich im Energiesparmodus.\n</li><li><code>CANSM_SILENT_COMMUNICATION</code>: Abhörmodus; Empfang aktiv, Senden unterbunden.\n</li><li><code>CANSM_FULL_COMMUNICATION</code>: Vollständiger Kommunikationsbetrieb für Senden und Empfangen.\n</li></ul>\n<p class=\"fig-p\">Pseudo-Zustände / Startpunkt:</p>\n<ul class=\"fig-list\"><li><code>PowerOff</code> (Initialzustand / schwarzer Kreis) mit Transition <code>PowerOn</code>.\n</li></ul>\n<p class=\"fig-p\">Beteiligte Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>CanSM als zustandsführendes Modul.\n</li><li>Angesteuerte Entitäten und Treiber über Aktionen: CAN Transceiver Driver, CAN Controller Driver (CanIf / MCAL) und PDU-Router / Com-PDU-Gruppenverwaltung.\n</li><li>Modus-Benachrichtigung (<code>mode notification</code>) an den Communication Manager (ComM).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf und Zustandsübergänge:</p>\n<ol class=\"fig-list\"><li><code>PowerOn</code> führt aus dem Zustand <code>PowerOff</code> in <code>CANSM_UNINITED</code>.\n<ul class=\"fig-list\"><li>Bei <code>No initialisation</code> verbleibt das System über eine Selbsttransition in <code>CANSM_UNINITED</code>.\n</li></ul>\n</li><li>Bei <code>Initialisation</code> wechselt das System von <code>CANSM_UNINITED</code> nach <code>CANSM_NO_COMMUNICATION</code>. Aktionen: CAN-Transceiver auf Standby schalten, CAN-Controller in den Sleep-Modus versetzen, Modus-Benachrichtigung absetzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_NO_COMMUNICATION</code> bewirkt <code>&quot;Full communication&quot; not requested</code> eine Selbsttransition ohne Zustandswechsel.\n</li></ul>\n</li><li>Von <code>CANSM_NO_COMMUNICATION</code> nach <code>CANSM_FULL_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; requested</code>. Aktionen: Transceiver auf Normalbetrieb setzen, Controller starten, RX- und TX-PDU-Gruppen starten, Modus-Benachrichtigung absetzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_FULL_COMMUNICATION</code> bewirkt <code>&quot;Full communication&quot; requested</code> eine interne/Selbsttransition.\n</li></ul>\n</li><li>Von <code>CANSM_FULL_COMMUNICATION</code> nach <code>CANSM_SILENT_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; not requested</code>. Aktionen: TX-PDU-Gruppe stoppen, PDU-Modus auf <code>&quot;TX Offline&quot;</code> setzen.\n<ul class=\"fig-list\"><li>In <code>CANSM_SILENT_COMMUNICATION</code> bewirkt <code>&quot;Silent communication&quot; requested</code> eine Selbsttransition.\n</li></ul>\n</li><li>Von <code>CANSM_SILENT_COMMUNICATION</code> nach <code>CANSM_FULL_COMMUNICATION</code>: Auslöser ist <code>&quot;Full communication&quot; requested</code>. Aktionen: PDU-Modus auf <code>&quot;Online&quot;</code> setzen, TX-PDU-Gruppe starten, Modus-Benachrichtigung absetzen.\n</li><li>Von <code>CANSM_SILENT_COMMUNICATION</code> nach <code>CANSM_NO_COMMUNICATION</code>: Auslöser ist <code>&quot;No communication&quot; requested</code>. Aktionen: RX-PDU-Gruppe stoppen, CAN-Controller in den Sleep-Modus versetzen, Transceiver auf Standby setzen, Modus-Benachrichtigung absetzen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Kommunikationszustände und Transitionen des CanSM gemäß AUTOSAR-Spezifikation. Implementierer müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Zustandswechsel nur über die spezifizierten Trigger (Aufrufe durch ComM) erfolgen.\n</li><li>Alle geforderten Aktionen (Transceiver-Modus, Controller-Status, PDU-Gruppen-Freigaben und ComM-Modusbenachrichtigungen) synchron bzw. in der definierten Sequenz bei Zustandsübergängen ausgeführt werden.\n</li><li>Ungültige Anfragen durch entsprechende Selbsttransitionen abgewiesen bzw. ignoriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4ec9166911cfceb3", "to": "FIG-d213ab5e4ff49dc8", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
